    [6969] = { fac = "Alliance", ilvl = 15, k = "quest", name = "Elunite Dagger", note = "beginning of the quest or chain", q = 2, quest = "Weapons of Elunite", req = 10, spots = "1457,59.2,45.4,A", t = "Reward from the quest 'Weapons of Elunite'. Pick it over the other reward choices. Starts with Mathiel in Darnassus. Objective: &lt;name&gt;, I have crafted these weapons with the elunite you brought to me. &nbsp;Please, take whichever most suits you.And I must thank you. &nbsp;Working with elunite is both an honor and a pleasure.", zone = "Darnassus" },
    [6971] = { fac = "Alliance", ilvl = 31, k = "quest", name = "Fire Hardened Coif", note = "beginning of the quest or chain", q = 2, quest = "Grimand's Armor", req = 20, spots = "1453,51.6,12.2,A", t = "Reward from the quest 'Grimand's Armor'. Starts with Grimand Elmore in Stormwind City. Objective: I can barely believe it! &nbsp;Furen's technique was a success, and this armor should withstand tremendous levels of stress.Here you are, &lt;name&gt;. &nbsp;And thank you. &nbsp;I wouldn't have believed Furen's discovery if you hadn't gathered the materials I needed to test it myself.", zone = "Stormwind City" },
    [6972] = { fac = "Alliance", ilvl = 30, k = "quest", name = "Fire Hardened Hauberk", note = "beginning of the quest or chain", q = 3, quest = "Furen's Armor", req = 20, spots = "1453,57.4,16,A", t = "Reward from the quest 'Furen's Armor'. Starts with Furen Longbeard in Stormwind City. Objective: Here's your armor, &lt;name&gt;. &nbsp;This will stand up to the strongest assaults or my name isn't Furen Longbeard!And I have to thank you. &nbsp;I learned a lot while working with the materials you brought me. &nbsp;I think I'll have another breakthrough one day!I'm going to send what I learned to other blacksmiths of the Alliance.I'll tell them you were a big help, and maybe they'll want to return the favor.", zone = "Stormwind City" },
    [6973] = { fac = "Alliance", ilvl = 29, k = "quest", name = "Fire Hardened Leggings", note = "beginning of the quest or chain", q = 2, quest = "Mathiel's Armor", req = 20, spots = "1457,59.2,45.4,A", t = "Reward from the quest 'Mathiel's Armor'. The quest is in Darnassus. Objective: I have finished with your piece of armor, and I am quite pleased. &nbsp;Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.Thank you, &lt;name&gt;. &nbsp;And may this serve you well in future battles.", zone = "Darnassus" },
    [6974] = { fac = "Alliance", ilvl = 31, k = "quest", name = "Fire Hardened Gauntlets", note = "beginning of the quest or chain", q = 2, quest = "Klockmort's Creation", req = 20, spots = "1455,68,46.8,A", t = "Reward from the quest 'Klockmort's Creation'. Starts with Klockmort Spannerspan in Ironforge. Objective: Here's your armor, &lt;name&gt;. &nbsp;Furen's process worked brilliantly! &nbsp;Perfectly! &nbsp;Marvelously, truly!You could run this armor over with a siege engine and it would spring right back into shape!", zone = "Ironforge" },
    [6975] = { ilvl = 40, k = "quest", name = "Whirlwind Axe", q = 3, quest = "Whirlwind Weapon", req = 30, t = "Reward from the quest 'Whirlwind Weapon'. Pick it over the other reward choices. Starts with Bath'rah the Windwatcher in Alterac Mountains. Objective: I have the whirlwind heart, and am ready to place it within your vessel of choice.Choose your weapon, &lt;name&gt;, and know that its power is the power of Cyclonian.", zone = "Alterac Mountains" },
    [6976] = { ilvl = 40, k = "quest", name = "Whirlwind Warhammer", q = 3, quest = "Whirlwind Weapon", req = 30, t = "Reward from the quest 'Whirlwind Weapon'. Pick it over the other reward choices. Starts with Bath'rah the Windwatcher in Alterac Mountains. Objective: I have the whirlwind heart, and am ready to place it within your vessel of choice.Choose your weapon, &lt;name&gt;, and know that its power is the power of Cyclonian.", zone = "Alterac Mountains" },
