    [7115] = { fac = "Horde", ilvl = 15, k = "quest", name = "Heirloom Axe", note = "beginning of the quest or chain", q = 2, quest = "Heirloom Weapon", req = 10, spots = "1420,61.8,52.4,H", t = "Reward from the quest 'Heirloom Weapon'. Pick it over the other reward choices. Starts with Coleman Farthing in Tirisfal Glades. Objective: I will keep three of the weapons you returned to me, as mementos of my pain and loss. &nbsp;But please, &lt;name&gt;, choose your favorite of the heirlooms and keep it for yourself.May it serve you greater than it served its cursed, former owners.", zone = "Tirisfal Glades" },
