    [7118] = { fac = "Horde", ilvl = 15, k = "quest", name = "Heirloom Sword", note = "beginning of the quest or chain", q = 2, quest = "Heirloom Weapon", req = 10, spots = "1420,61.8,52.4,H", t = "Reward from the quest 'Heirloom Weapon'. Pick it over the other reward choices. Starts with Coleman Farthing in Tirisfal Glades. Objective: I will keep three of the weapons you returned to me, as mementos of my pain and loss. &nbsp;But please, &lt;name&gt;, choose your favorite of the heirlooms and keep it for yourself.May it serve you greater than it served its cursed, former owners.", zone = "Tirisfal Glades" },
    [7129] = { fac = "Horde", ilvl = 31, k = "quest", name = "Brutal Gauntlets", note = "beginning of the quest or chain", q = 2, quest = "Brutal Gauntlets", req = 20, spots = "1411,56.2,74.4,H", t = "Reward from the quest 'Brutal Gauntlets'. Starts with Ula'elek in Durotar. Objective: Thank you, &lt;name&gt;. &nbsp;These gauntlets are my best work. &nbsp;Take them. In wearing them, you bring honor to me and my ancestors.", zone = "Durotar" },
    [7130] = { fac = "Horde", ilvl = 31, k = "quest", name = "Brutal Helm", note = "beginning of the quest or chain", q = 2, quest = "Brutal Helm", req = 20, spots = "1456,38,56.4,H", t = "Reward from the quest 'Brutal Helm'. Starts with Orm Stonehoof in Thunder Bluff. Objective: I give this helm to you.Great deeds brought you to me, &lt;name&gt;, and Earthmother willing... even greater deeds lie before you. A quest. Always up to date.", zone = "Thunder Bluff" },
    [7132] = { fac = "Horde", ilvl = 29, k = "quest", name = "Brutal Legguards", note = "beginning of the quest or chain", q = 2, quest = "Brutal Legguards", req = 20, spots = "1458,62.4,39.2,H", t = "Reward from the quest 'Brutal Legguards'. Starts with Velora Nitely in Undercity. Objective: Here are your legguards, &lt;name&gt;. &nbsp;Let me know how they fit or if you need any modifications. &nbsp;I aim to please! &nbsp;At least I used to.These days I don't care much for my craft. &nbsp;But it beats being a mindless minion of the Scourge!I guess.", zone = "Undercity" },
    [7133] = { fac = "Horde", ilvl = 30, k = "quest", name = "Brutal Hauberk", note = "beginning of the quest or chain", q = 3, quest = "Brutal Hauberk", req = 20, spots = "1413,57.2,30.2,H", t = "Reward from the quest 'Brutal Hauberk'. Starts with Thun'grim Firegaze in The Barrens. Objective: I am sure you endured much hardship and shed much blood on my task, &lt;name&gt;. &nbsp;Here is the product of your toil.May you wear it well, and may you one day return here with stories of its service to you.", zone = "The Barrens" },
