    [7507] = { fac = "Alliance", ilvl = 10, k = "quest", name = "Arcane Orb", note = "beginning of the quest or chain", q = 2, quest = "Mage-tastic Gizmonitor", req = 10, spots = "1426,47.4,52,A", t = "Reward from the quest 'Mage-tastic Gizmonitor'. Pick it over the other reward choices. Starts with Bink in Ironforge. Objective: Bring Bink her Mage-tastic Gizmonitor.", zone = "Ironforge" },
    [7508] = { fac = "Alliance", ilvl = 10, k = "quest", name = "Ley Orb", note = "beginning of the quest or chain", q = 2, quest = "Mirror Lake", req = 10, spots = "1429,43.2,66.2,A", t = "Reward from the quest 'Mirror Lake'. Pick it over the other reward choices. Starts with Jennea Cannon in Stormwind City. Objective: Bring a Mirror Lake sample to Jennea Cannon in Stormwind.", zone = "Stormwind City" },
    [7509] = { fac = "Alliance", ilvl = 20, k = "quest", name = "Manaweave Robe", note = "beginning of the quest or chain", q = 2, quest = "Manaweave Robe", req = 15, spots = "1453,41.6,76.6,A", t = "Reward from the quest 'Manaweave Robe'. Starts with Wynne Larson in Stormwind City. Objective: Here is your robe. &nbsp;It's one of my best made yet! &nbsp;Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!", zone = "Stormwind City" },
    [7510] = { fac = "Horde", ilvl = 20, k = "quest", name = "Lesser Spellfire Robes", note = "beginning of the quest or chain", q = 2, quest = "Spellfire Robes", req = 15, spots = "1458,70.2,30.2,H", t = "Reward from the quest 'Spellfire Robes'. Starts with Rhiannon Davis in Undercity. Objective: Here are your robes, &lt;name&gt;. &nbsp;Wear them well.", zone = "Undercity" },
    [7511] = { fac = "Alliance", ilvl = 31, k = "quest", name = "Astral Knot Robe", note = "beginning of the quest or chain", q = 2, quest = "Astral Knot Garment", req = 26, spots = "1453,41.6,76.6,A", t = "Reward from the quest 'Astral Knot Garment'. Pick it over the other reward choices. Starts with Wynne Larson in Stormwind City. Objective: Your garment is ready! &nbsp;And that silk you gathered was so nice... you don't mind if I made it a little short so that I'd have some silk left over for me, do you?I'm only joking. &nbsp;It'll fit you great, and will be perfect for both adventure and formal dining. &nbsp;Enjoy!", zone = "Stormwind City" },
    [7512] = { fac = "Horde", ilvl = 31, k = "quest", name = "Nether-lace Robe", note = "beginning of the quest or chain", q = 2, quest = "Nether-lace Garment", req = 26, spots = "1413,52.2,31.6,H", t = "Reward from the quest 'Nether-lace Garment'. Pick it over the other reward choices. Starts with Kil'hala in The Barrens. Objective: Here is your nether-lace, &lt;name&gt;. &nbsp;It is both comfortable and durable, and holds the magic of the laughing sisters' hair.Enjoy, and if you find it amenable, please mention so to Deino. &nbsp;She is a &lt;class&gt; on whose good side I wish to stay...", zone = "The Barrens" },
    [7513] = { ilvl = 40, k = "quest", name = "Ragefire Wand", q = 3, quest = "Mage's Wand", req = 40, t = "Reward from the quest 'Mage's Wand'. Pick it over the other reward choices. The chain starts with Tabetha in Dustwallow Marsh. Rituals of Power sends you into Scarlet Monastery Library. That step is level 40.", zone = "Dustwallow Marsh" },
    [7514] = { ilvl = 40, k = "quest", name = "Icefury Wand", q = 3, quest = "Mage's Wand", req = 40, t = "Reward from the quest 'Mage's Wand'. Pick it over the other reward choices. The chain starts with Tabetha in Dustwallow Marsh. Rituals of Power sends you into Scarlet Monastery Library. That step is level 40.", zone = "Dustwallow Marsh" },
    [7515] = { ilvl = 40, k = "quest", name = "Celestial Orb", q = 3, quest = "Celestial Power", req = 35, t = "Reward from the quest 'Celestial Power'. Pick it over the other reward choices. Starts with Tabetha in Dustwallow Marsh. Objective: You should be proud of yourself, &lt;name&gt;. &nbsp;Many mages have fallen to the creatures you faced.The Celestial Orb is ready. &nbsp;Or if you'd like I can mount it atop a staff. &nbsp;It's up to you. &nbsp;I'd prefer the orb, but who am I to judge?", zone = "Dustwallow Marsh" },
