    [9515] = { fac = "Horde", ilvl = 31, k = "quest", name = "Nether-lace Tunic", note = "beginning of the quest or chain", q = 2, quest = "Nether-lace Garment", req = 26, spots = "1413,52.2,31.6,H", t = "Reward from the quest 'Nether-lace Garment'. Pick it over the other reward choices. Starts with Kil'hala in The Barrens. Objective: Here is your nether-lace, &lt;name&gt;. &nbsp;It is both comfortable and durable, and holds the magic of the laughing sisters' hair.Enjoy, and if you find it amenable, please mention so to Deino. &nbsp;She is a &lt;class&gt; on whose good side I wish to stay...", zone = "The Barrens" },
    [9516] = { fac = "Alliance", ilvl = 31, k = "quest", name = "Astral Knot Blouse", note = "beginning of the quest or chain", q = 2, quest = "Astral Knot Garment", req = 26, spots = "1453,41.6,76.6,A", t = "Reward from the quest 'Astral Knot Garment'. Pick it over the other reward choices. Starts with Wynne Larson in Stormwind City. Objective: Your garment is ready! &nbsp;And that silk you gathered was so nice... you don't mind if I made it a little short so that I'd have some silk left over for me, do you?I'm only joking. &nbsp;It'll fit you great, and will be perfect for both adventure and formal dining. &nbsp;Enjoy!", zone = "Stormwind City" },
