    [12066] = { ilvl = 58, k = "quest", name = "Shaleskin Cape", q = 2, quest = "A Taste of Flame", req = 52, t = "Reward from the quest 'A Taste of Flame'. Pick it over the other reward choices. Starts with Cyrus Therepentous in Burning Steppes. Objective: Travel to Blackrock Depths and slay Bael'Gar.You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.Return the Encased Fiery Essence to Cyrus Therepentous.", zone = "Blackrock Depths" },
