    [12108] = { fac = "Horde", ilvl = 58, k = "quest", name = "Basaltscale Armor", q = 2, quest = "The Rise of the Machines", req = 52, t = "Reward from the quest 'The Rise of the Machines'. Pick it over the other reward choices. Starts with Lotwil Veriatus in Badlands. Objective: Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", zone = "Blackrock Depths" },
