    [13216] = { ilvl = 61, k = "quest", name = "Crown of the Penitent", q = 3, quest = "Houses of the Holy", req = 55, t = "Reward from the quest 'Houses of the Holy'. Pick it over the other reward choices. Starts with Leonid Barthalomew the Revered in Eastern Plaguelands. Objective: Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", zone = "Stratholme" },
    [13217] = { ilvl = 61, k = "quest", name = "Band of the Penitent", q = 3, quest = "Houses of the Holy", req = 55, t = "Reward from the quest 'Houses of the Holy'. Pick it over the other reward choices. Starts with Leonid Barthalomew the Revered in Eastern Plaguelands. Objective: Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", zone = "Stratholme" },
