    [13474] = { ilvl = 56, k = "quest", name = "Farmer Dalson's Shotgun", q = 2, quest = "Locked Away", req = 52, t = "Reward from the quest 'Locked Away'. The quest is in Western Plaguelands. Objective: ProgressAn extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock. &nbsp;The front of the cabinet is deeply scratched and marked. &nbsp;This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.If you are going to open this cabinet, you will need to find the key.", zone = "Western Plaguelands" },
    [13475] = { ilvl = 55, k = "quest", name = "Dalson Family Wedding Ring", q = 2, quest = "Locked Away", req = 52, t = "Reward from the quest 'Locked Away'. The quest is in Western Plaguelands. Objective: ProgressAn extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock. &nbsp;The front of the cabinet is deeply scratched and marked. &nbsp;This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.If you are going to open this cabinet, you will need to find the key.", zone = "Western Plaguelands" },
