    [13982] = { ilvl = 63, k = "quest", name = "Warblade of Caer Darrow", q = 3, quest = "The Lich, Ras Frostwhisper", req = 57, t = "Reward from the quest 'The Lich, Ras Frostwhisper'. Pick it over the other reward choices. Starts with Magistrate Marduke in Western Plaguelands. Objective: Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", zone = "Scholomance" },
    [13986] = { ilvl = 63, k = "quest", name = "Crown of Caer Darrow", q = 3, quest = "The Lich, Ras Frostwhisper", req = 57, t = "Reward from the quest 'The Lich, Ras Frostwhisper'. Pick it over the other reward choices. Starts with Magistrate Marduke in Western Plaguelands. Objective: Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", zone = "Scholomance" },
