    [15202] = { fac = "Alliance", ilvl = 18, k = "quest", name = "Wildkeeper Leggings", note = "beginning of the quest or chain", q = 2, quest = "The Blackwood Corrupted", req = 15, spots = "1439,37.4,40.2,A", t = "Reward from the quest 'The Blackwood Corrupted'. Pick it over the other reward choices. Starts with Thundris Windweaver in Darkshore. Objective: Fill the Empty Cleansing Bowl at the Auberdine Moonwell.Gather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.Mix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.Take the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.", zone = "Darkshore" },
