    [15799] = { fac = "Horde", ilvl = 58, k = "quest", name = "Heroic Commendation Medal", note = "beginning of the quest or chain", q = 2, quest = "Mission Accomplished!", req = 50, spots = "1420,83,69,H", t = "Reward from the quest 'Mission Accomplished!'. Starts with High Executor Derrington in Tirisfal Glades. Objective: &lt;name&gt;, your successful re-engineering of the cauldrons is a tremendous victory for us!Let all within my presence hear: for service to the Forsaken and to the Horde as a whole above and beyond what was expected - in the face of overwhelming odds and incredible danger, might I add - I give &lt;name&gt; this, and I extend upon him our undying gratitude as a true hero of the Horde. &nbsp;Huzzah!", zone = "Western Plaguelands" },
