    [16658] = { fac = "Horde", ilvl = 32, k = "quest", name = "Wildhunter Cloak", q = 2, quest = "The Hunt Completed", req = 20, t = "Reward from the quest 'The Hunt Completed'. Starts with Senani Thunderheart in Ashenvale. Objective: &lt;name&gt;, you have slain all three beasts that comprise the Ashenvale Hunt. &nbsp;You have brought me adequate proof of their demise; there is no question of your strength and tenacity. &nbsp;The blood of a hunter streaks through your veins, and you should be commended!Please, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today. &nbsp;May your ancestors watch over you!", zone = "Ashenvale" },
