    [17523] = { ilvl = 58, k = "quest", name = "Smokey's Drape", q = 2, quest = "When Smokey Sings, I Get Violent", req = 54, t = "Reward from the quest 'When Smokey Sings, I Get Violent'. Starts with Smokey LaRue in Eastern Plaguelands. Objective: Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.Once you plant the bomb, leave the building and marvel at your handiwork.By the way, Smokey's Special Compound is rather... unstable.", zone = "Eastern Plaguelands" },
