    [17770] = { ilvl = 49, k = "quest", name = "Branchclaw Gauntlets", q = 3, quest = "Vyletongue Corruption", req = 41, t = "Reward from the quest 'Vyletongue Corruption'. Pick it over the other reward choices. Starts with Vark Battlescar in Maraudon. Objective: Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", zone = "Maraudon" },
