    [17902] = { fac = "Alliance", ilvl = 60, k = "quest", name = "Stormpike Insignia Rank 4", q = 3, quest = "Earned Reverence", req = 51, t = "Reward from the quest 'Earned Reverence'. Starts with Warmaster Laggrond in Alterac Mountains. Objective: ProgressSo many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.Present your insignia.", zone = "Alterac Valley" },
    [17903] = { fac = "Alliance", ilvl = 60, k = "quest", name = "Stormpike Insignia Rank 5", q = 3, quest = "Legendary Heroes", req = 51, t = "Reward from the quest 'Legendary Heroes'. Starts with Lieutenant Haggerdin in Alterac Mountains. Objective: ProgressBefore me stands an exalted hero of the Alliance.&lt;Lieutenant Haggerdin salutes.&gt;Few have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!Present your insignia.", zone = "Alterac Valley" },
    [17904] = { fac = "Alliance", ilvl = 60, k = "quest", name = "Stormpike Insignia Rank 6", q = 4, quest = "The Eye of Command", req = 51, t = "Reward from the quest 'The Eye of Command'. Starts with Warmaster Laggrond in Alterac Mountains. Objective: ProgressDrek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.You have earned the Eye of Command.Present your insignia, Commander &lt;name&gt;.", zone = "Alterac Valley" },
    [17906] = { fac = "Horde", ilvl = 60, k = "quest", name = "Frostwolf Insignia Rank 3", q = 2, quest = "Honored Amongst the Clan", req = 51, t = "Reward from the quest 'Honored Amongst the Clan'. Starts with Warmaster Laggrond in Alterac Mountains. Objective: ProgressIt is good to see you again, &lt;class&gt;. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.Your time has come again, &lt;name&gt;. You have earned a new ranking and as such, a new insignia denoting this rise in stature.Present your insignia.", zone = "Alterac Valley" },
    [17907] = { fac = "Horde", ilvl = 60, k = "quest", name = "Frostwolf Insignia Rank 4", q = 3, quest = "Earned Reverence", req = 51, t = "Reward from the quest 'Earned Reverence'. Starts with Warmaster Laggrond in Alterac Mountains. Objective: ProgressSo many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.Present your insignia.", zone = "Alterac Valley" },
