    [18760] = { fac = "Horde", ilvl = 62, k = "world", name = "Necromantic Band", npc = "Death Knight Darkreaver", q = 3, req = 57, s = "rare", t = "Drops from Death Knight Darkreaver." },
    [18762] = { ilvl = 54, k = "quest", name = "Shard of the Green Flame", q = 3, quest = "Kroshius' Infernal Core", req = 50, t = "Reward from the quest 'Kroshius' Infernal Core'. Starts with Impsy in Felwood. Objective: Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.Return Kroshius' Infernal Core to Niby the Almighty in Felwood.", zone = "Felwood" },
    [18803] = { ilvl = 70, k = "world", name = "Hyperthermically Insulated Lava Dredger", note = "one of the spots to farm it", npc = "a container", q = 4, req = 60, s = "object", spots = "1427,34.8,85.3,", t = "Found in a container.", zone = "Searing Gorge" },
