    [18807] = { fac = "Horde", ilvl = 62, k = "quest", name = "Helm of Latent Power", note = "beginning of the quest or chain", q = 3, quest = "The Darkreaver Menace", req = 58, spots = "1454,38.4,36,H", t = "Reward from the quest 'The Darkreaver Menace'. Starts with Sagorne Creststrider in Orgrimmar. Objective: Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", zone = "Orgrimmar" },
    [18948] = { ilvl = 32, k = "craft", mats = "4234,8,Heavy Leather;4236,2,Cured Heavy Hide;5498,4,Small Lustrous Pearl;4461,1,Raptor Hide;5637,4,Large Fang", name = "Barbaric Bracers", note = "the trainer that teaches this", prof = "Leatherworking", q = 3, req = 27, skill = 130, spell = 23399, spots = "1453,71.7,63,A;1454,62.8,44.1,H", t = "Crafted with Leatherworking (requires skill 1)." },
    [18957] = { fac = "Alliance", ilvl = 10, k = "quest", name = "Brushwood Blade", note = "beginning of the quest or chain", q = 2, quest = "Druid of the Claw", req = 3, spots = "1438,45,61.4,A", t = "Reward from the quest 'Druid of the Claw'. Pick it over the other reward choices. Starts with Oben Rageclaw in Teldrassil. Objective: Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.", zone = "Teldrassil" },
    [19024] = { ilvl = 55, k = "quest", name = "Arena Grand Master", q = 3, quest = "Arena Grandmaster", req = 50, t = "Reward from the quest 'Arena Grandmaster'. Starts with Short John Mithril in Stranglethorn Vale. Objective: ProgressAvast Lubber! &nbsp; Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena! &nbsp; Arrrr!", zone = "Stranglethorn Vale" },
    [19037] = { fac = "Horde", ilvl = 48, k = "quest", name = "Emerald Peak Spaulders", q = 2, quest = "Zukk'ash Report", req = 39, t = "Reward from the quest 'Zukk'ash Report'. Pick it over the other reward choices. Starts with Hadoken Swiftstrider in Orgrimmar. Objective: Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar.", zone = "Feralas" },
    [19038] = { fac = "Horde", ilvl = 48, k = "quest", name = "Ring of Subtlety", q = 2, quest = "Zukk'ash Report", req = 39, t = "Reward from the quest 'Zukk'ash Report'. Pick it over the other reward choices. Starts with Hadoken Swiftstrider in Orgrimmar. Objective: Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar.", zone = "Feralas" },
    [19039] = { ilvl = 48, k = "quest", name = "Zorbin's Water Resistant Hat", q = 2, quest = "Fuel for the Zapping", req = 45, t = "Reward from the quest 'Fuel for the Zapping'. Starts with Zorbin Fandazzle in Feralas. Objective: Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", zone = "Feralas" },
    [19040] = { ilvl = 48, k = "quest", name = "Zorbin's Mega-Slicer", q = 2, quest = "Zapped Giants", req = 45, t = "Reward from the quest 'Zapped Giants'. Starts with Zorbin Fandazzle in Feralas. Objective: Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", zone = "Feralas" },
    [19041] = { fac = "Alliance", ilvl = 48, k = "quest", name = "Pratt's Handcrafted Tunic", q = 2, quest = "Improved Quality", req = 40, t = "Reward from the quest 'Improved Quality'. Starts with Pratt McGrubben in Feralas. Objective: Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.", zone = "Feralas" },
