    [19106] = { ilvl = 63, k = "quest", name = "Ice Barbed Spear", note = "beginning of the quest or chain", q = 3, quest = "The Legend of Korrak", req = 51, spots = "1416,39.5,81.2,A;1416,62.3,58.9,H", t = "Reward from the quest 'The Legend of Korrak'. Pick it over the other reward choices. Objective: According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.Should Korrak make himself known, destroy him and return to Warmaster Laggrond.", zone = "Alterac Valley" },
    [19107] = { ilvl = 63, k = "quest", name = "Bloodseeker", note = "beginning of the quest or chain", q = 3, quest = "The Legend of Korrak", req = 51, spots = "1416,39.5,81.2,A;1416,62.3,58.9,H", t = "Reward from the quest 'The Legend of Korrak'. Pick it over the other reward choices. Objective: According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.Should Korrak make himself known, destroy him and return to Warmaster Laggrond.", zone = "Alterac Valley" },
    [19108] = { ilvl = 63, k = "quest", name = "Wand of Biting Cold", note = "beginning of the quest or chain", q = 3, quest = "The Legend of Korrak", req = 51, spots = "1416,39.5,81.2,A;1416,62.3,58.9,H", t = "Reward from the quest 'The Legend of Korrak'. Pick it over the other reward choices. Objective: According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.Should Korrak make himself known, destroy him and return to Warmaster Laggrond.", zone = "Alterac Valley" },
    [19109] = { ilvl = 63, k = "world", name = "Deep Rooted Ring", npc = "Ivus the Forest Lord", q = 3, req = 58, s = "boss", t = "Drops from Ivus the Forest Lord.", zone = "Alterac Valley" },
    [19114] = { fac = "Horde", ilvl = 51, k = "quest", name = "Highland Bow", q = 2, quest = "Return to Primal Torntusk", req = 46, t = "Reward from the quest 'Return to Primal Torntusk'. Pick it over the other reward choices.", zone = "The Hinterlands" },
    [19115] = { fac = "Horde", ilvl = 51, k = "quest", name = "Flask of Forest Mojo", q = 2, quest = "Return to Primal Torntusk", req = 46, t = "Reward from the quest 'Return to Primal Torntusk'. Pick it over the other reward choices.", zone = "The Hinterlands" },
    [19116] = { fac = "Horde", ilvl = 50, k = "quest", name = "Greenleaf Handwraps", q = 2, quest = "Separation Anxiety", req = 46, t = "Reward from the quest 'Separation Anxiety'. Pick it over the other reward choices. Starts with Huntsman Markhor in The Hinterlands. Objective: Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", zone = "The Hinterlands" },
    [19117] = { fac = "Horde", ilvl = 50, k = "quest", name = "Laquered Wooden Plate Legplates", q = 2, quest = "Separation Anxiety", req = 46, t = "Reward from the quest 'Separation Anxiety'. Pick it over the other reward choices. Starts with Huntsman Markhor in The Hinterlands. Objective: Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", zone = "The Hinterlands" },
    [19118] = { fac = "Horde", ilvl = 50, k = "quest", name = "Nature's Breath", q = 2, quest = "Dark Vessels", req = 46, t = "Reward from the quest 'Dark Vessels'. Starts with Primal Torntusk in The Hinterlands. Objective: Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", zone = "The Hinterlands" },
    [19119] = { fac = "Horde", ilvl = 50, k = "quest", name = "Owlbeast Hide Gloves", q = 2, quest = "The Final Message to the Wildhammer", req = 44, t = "Reward from the quest 'The Final Message to the Wildhammer'. Starts with Otho Moji'ko in The Hinterlands. Objective: Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.Beware of angry Wildhammer dwarves and unruly members of the Alliance.", zone = "The Hinterlands" },
    [19120] = { fac = "Horde", ilvl = 51, k = "quest", name = "Rune of the Guard Captain", q = 2, quest = "Job Opening: Guard Captain of Revantusk Village", req = 46, t = "Reward from the quest 'Job Opening: Guard Captain of Revantusk Village'. The quest is in The Hinterlands. Objective: You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", zone = "The Hinterlands" },
    [19121] = { fac = "Horde", ilvl = 51, k = "quest", name = "Deep Woodlands Cloak", q = 3, quest = "Wanted: Vile Priestess Hexx and Her Minions", req = 46, t = "Reward from the quest 'Wanted: Vile Priestess Hexx and Her Minions'. Pick it over the other reward choices. The quest is in The Hinterlands. Objective: You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", zone = "The Hinterlands" },
    [19123] = { ilvl = 48, k = "quest", name = "Everwarm Handwraps", q = 2, quest = "STOLEN: Smithing Tuyere and Lookout's Spyglass", req = 45, t = "Reward from the quest 'STOLEN: Smithing Tuyere and Lookout's Spyglass'. Pick it over the other reward choices. The quest is in Searing Gorge. Objective: Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", zone = "Searing Gorge" },
    [19124] = { ilvl = 48, k = "quest", name = "Slagplate Leggings", q = 2, quest = "STOLEN: Smithing Tuyere and Lookout's Spyglass", req = 45, t = "Reward from the quest 'STOLEN: Smithing Tuyere and Lookout's Spyglass'. Pick it over the other reward choices. The quest is in Searing Gorge. Objective: Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", zone = "Searing Gorge" },
    [19125] = { ilvl = 49, k = "quest", name = "Seared Mail Girdle", q = 2, quest = "Fiery Menace!", req = 45, t = "Reward from the quest 'Fiery Menace!'. Starts with Hansel Heavyhands in Searing Gorge. Objective: Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", zone = "Searing Gorge" },
    [19126] = { ilvl = 49, k = "quest", name = "Slagplate Gauntlets", q = 2, quest = "Curse These Fat Fingers", req = 45, t = "Reward from the quest 'Curse These Fat Fingers'. Starts with Hansel Heavyhands in Searing Gorge. Objective: Hansel Heavyhands wants you to kill 20 Heavy War Golems.The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", zone = "Searing Gorge" },
    [19127] = { ilvl = 50, k = "quest", name = "Charred Leather Tunic", q = 2, quest = "WANTED: Overseer Maltorius", req = 45, t = "Reward from the quest 'WANTED: Overseer Maltorius'. Pick it over the other reward choices. The quest is in Searing Gorge. Objective: Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", zone = "Searing Gorge" },
    [19128] = { ilvl = 50, k = "quest", name = "Seared Mail Vest", q = 2, quest = "WANTED: Overseer Maltorius", req = 45, t = "Reward from the quest 'WANTED: Overseer Maltorius'. Pick it over the other reward choices. The quest is in Searing Gorge. Objective: Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", zone = "Searing Gorge" },
    [19139] = { ilvl = 71, k = "world", name = "Fireguard Shoulders", note = "one of the spots to farm it", npc = "a container", q = 4, req = 60, s = "object", spots = "1427,34.8,85.3,", t = "Found in a container.", zone = "Searing Gorge" },
