    [19573] = { fac = "Alliance", ilvl = 33, k = "vendor", name = "Lorekeeper's Staff", npc = "Illiyana Moonblaze", q = 3, req = 28, t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19576] = { ilvl = 68, k = "quest", name = "Strength of Mugamba", q = 3, quest = "Strength of Mount Mugamba", req = 58, t = "Reward from the quest 'Strength of Mount Mugamba'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: ProgressIt is good to see you in good health, &lt;name&gt;. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.Give me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", zone = "Zul'Gurub" },
    [19577] = { ilvl = 65, k = "quest", name = "Rage of Mugamba", q = 4, quest = "The Rage of Mugamba", req = 58, t = "Reward from the quest 'The Rage of Mugamba'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: ProgressKing Rastakhan sends his regards, Master &lt;name&gt;. Such an honor has never been given to one outside the Zandalar tribe.Give me your talisman so that I may enhance it once more. Know that the Rage of Mugamba is now intrinsically connected to your very soul.", zone = "Zul'Gurub" },
    [19578] = { fac = "Horde", ilvl = 65, k = "vendor", name = "Berserker Bracers", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 60, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19580] = { fac = "Horde", ilvl = 55, k = "vendor", name = "Berserker Bracers", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 50, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
