    [19582] = { fac = "Horde", ilvl = 65, k = "vendor", name = "Windtalker's Wristguards", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 60, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19583] = { fac = "Horde", ilvl = 55, k = "vendor", name = "Windtalker's Wristguards", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 50, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19584] = { fac = "Horde", ilvl = 45, k = "vendor", name = "Windtalker's Wristguards", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 40, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19586] = { fac = "Alliance", ilvl = 68, k = "quest", name = "Heathen's Brand", q = 3, quest = "The Heathen's Brand", req = 58, t = "Reward from the quest 'The Heathen's Brand'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Know this, heathen: A catastrophe has brought us together. Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people. Wear this brand around your neck. It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.Continue to serve our people and I will amplify the power of the brand.", zone = "Zul'Gurub" },
    [19587] = { fac = "Horde", ilvl = 65, k = "vendor", name = "Forest Stalker's Bracers", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 60, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19588] = { fac = "Alliance", ilvl = 65, k = "quest", name = "Hero's Brand", q = 4, quest = "The Hero's Brand", req = 58, t = "Reward from the quest 'The Hero's Brand'.", zone = "Zul'Gurub" },
    [19589] = { fac = "Horde", ilvl = 55, k = "vendor", name = "Forest Stalker's Bracers", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 50, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19590] = { fac = "Horde", ilvl = 45, k = "vendor", name = "Forest Stalker's Bracers", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 40, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19593] = { ilvl = 68, k = "quest", name = "The Eye of Zuldazar", q = 3, quest = "The Eye of Zuldazar", req = 58, t = "Reward from the quest 'The Eye of Zuldazar'. Starts with Al'tabim the All-Seeing in Stranglethorn Vale. Objective: ProgressTales of your battles against the Gurubashi are whispered in the winds, &lt;class&gt;. Even royalty is beginning to talk of your deeds. It is rumored that King Rastakhan even mentioned you by name.The time has come to imbue the Eye. Hand me the talisman and I shall perform the service.", zone = "Zul'Gurub" },
    [19594] = { ilvl = 65, k = "quest", name = "The All-Seeing Eye of Zuldazar", q = 4, quest = "The All-Seeing Eye of Zuldazar", req = 58, t = "Reward from the quest 'The All-Seeing Eye of Zuldazar'.", zone = "Zul'Gurub" },
    [19595] = { fac = "Horde", ilvl = 65, k = "vendor", name = "Dryad's Wrist Bindings", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 60, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19596] = { fac = "Horde", ilvl = 55, k = "vendor", name = "Dryad's Wrist Bindings", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 50, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19597] = { fac = "Horde", ilvl = 45, k = "vendor", name = "Dryad's Wrist Bindings", note = "vendor that sells this", npc = "Illiyana Moonblaze", q = 4, req = 40, spots = "1413,46.6,8.4,H", t = "Bought from Illiyana Moonblaze.", zone = "Ashenvale" },
    [19600] = { ilvl = 68, k = "quest", name = "Pebble of Kajaro", q = 3, quest = "The Pebble of Kajaro", req = 58, t = "Reward from the quest 'The Pebble of Kajaro'.", zone = "Zul'Gurub" },
    [19601] = { ilvl = 65, k = "quest", name = "Jewel of Kajaro", q = 4, quest = "The Jewel of Kajaro", req = 58, t = "Reward from the quest 'The Jewel of Kajaro'.", zone = "Zul'Gurub" },
    [19604] = { ilvl = 68, k = "quest", name = "Kezan's Taint", q = 3, quest = "Kezan's Taint", req = 58, t = "Reward from the quest 'Kezan's Taint'. Starts with Al'tabim the All-Seeing in Stranglethorn Vale. Objective: Accept this talisman, &lt;class&gt;. Accept it and use its power to strike down our mutual enemies.Know that around your neck you carry a piece of history. Kezan was once a grand territory of the Zandalar Empire. Alas, the taint of goblin trade princes would force out my proud brothers and sisters.Kezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness. Still to this day Kezan is considered sacred land to my people.", zone = "Zul'Gurub" },
    [19605] = { ilvl = 65, k = "quest", name = "Kezan's Unstoppable Taint", q = 4, quest = "Kezan's Unstoppable Taint", req = 58, t = "Reward from the quest 'Kezan's Unstoppable Taint'. Starts with Al'tabim the All-Seeing in Stranglethorn Vale. Objective: ProgressCall forth your demons, &lt;class&gt;. Let them bask in the energy of Kezan's Taint. Command them on the field of battle! Decimate the enemy!Yes... The time has come to apply the final enhancement to Kezan's Taint. Give me the talisman.", zone = "Zul'Gurub" },
    [19608] = { fac = "Horde", ilvl = 68, k = "quest", name = "Vision of Voodress", q = 3, quest = "Vision of Voodress", req = 58, t = "Reward from the quest 'Vision of Voodress'. Starts with Maywiki of Zuldazar in Stranglethorn Vale. Objective: ProgressSha-mon! Maywiki make a joke!&lt;Maywiki laughs.&gt;So, you been using the spirits and elements against our enemies in Zul'Gurub, eh? Spirits be praised!Maywiki gonna brighten your orb. Give it here, &lt;name&gt;.", zone = "Zul'Gurub" },
    [19609] = { fac = "Horde", ilvl = 65, k = "quest", name = "Unmarred Vision of Voodress", q = 4, quest = "The Unmarred Vision of Voodress", req = 58, t = "Reward from the quest 'The Unmarred Vision of Voodress'.", zone = "Zul'Gurub" },
    [19612] = { ilvl = 68, k = "quest", name = "Enchanted South Seas Kelp", q = 3, quest = "Enchanted South Seas Kelp", req = 58, t = "Reward from the quest 'Enchanted South Seas Kelp'. Starts with Maywiki of Zuldazar in Stranglethorn Vale. Objective: ProgressHow be that talisman, mon? It look like it be time to add a little more magic and mojo to its leaves. It need a little bloom in its wilt. Give it here and Maywiki fix it right up.", zone = "Zul'Gurub" },
    [19613] = { ilvl = 65, k = "quest", name = "Pristine Enchanted South Seas Kelp", q = 4, quest = "Pristine Enchanted South Seas Kelp", req = 58, t = "Reward from the quest 'Pristine Enchanted South Seas Kelp'.", zone = "Zul'Gurub" },
    [19616] = { ilvl = 68, k = "quest", name = "Zandalarian Shadow Talisman", q = 3, quest = "Zandalarian Shadow Talisman", req = 58, t = "Reward from the quest 'Zandalarian Shadow Talisman'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: ProgressImpressive, &lt;name&gt;. You have a gift for killing that I have not sensed in another in many years. Even Molthor is aware of the work that you have done for Zandalar. It is time to enhance your talisman further. Give it to me.", zone = "Zul'Gurub" },
    [19617] = { ilvl = 65, k = "quest", name = "Zandalarian Shadow Mastery Talisman", q = 4, quest = "Zandalarian Shadow Mastery Talisman", req = 58, t = "Reward from the quest 'Zandalarian Shadow Mastery Talisman'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: ProgressIt yearns to grow, &lt;name&gt;. The talisman has soaked in all that you have done. The thousands of troll corpses littering Zul'Gurub have fueled its power. Hand it to me and I shall make the final enhancement.", zone = "Zul'Gurub" },
    [19620] = { ilvl = 68, k = "quest", name = "Maelstrom's Tendril", q = 3, quest = "The Maelstrom's Tendril", req = 58, t = "Reward from the quest 'The Maelstrom's Tendril'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: ProgressAh, &lt;name&gt;, it is good to smell you again.You'll have to excuse my sense of humor. It can be most foul at times.I sense that you have caused great anguish to our enemies. The forces of Hakkar cry out your name in anger. This is most excellent.You have earned another weave on your talisman. Hand it to me.", zone = "Zul'Gurub" },
    [19621] = { ilvl = 65, k = "quest", name = "Maelstrom's Wrath", q = 4, quest = "Maelstrom's Wrath", req = 58, t = "Reward from the quest 'Maelstrom's Wrath'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: ProgressMolthor delivers word from King Rastakhan, &lt;name&gt;. The royal court is most impressed with your decimation of the Hakkari forces. I am to award you with the final weave in your talisman. Hand it to me.", zone = "Zul'Gurub" },
