    [19808] = { ilvl = 45, k = "world", name = "Rockhide Strongfish", npc = "Wooden Chair", q = 2, req = 40, s = "object", t = "Found in Wooden Chair." },
    [19822] = { ilvl = 65, k = "quest", name = "Zandalar Vindicator's Breastplate", q = 4, quest = "Paragons of Power: The Vindicator's Breastplate", req = 58, t = "Reward from the quest 'Paragons of Power: The Vindicator's Breastplate'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", zone = "Zul'Gurub" },
    [19823] = { ilvl = 61, k = "quest", name = "Zandalar Vindicator's Belt", q = 4, quest = "Paragons of Power: The Vindicator's Belt", req = 58, t = "Reward from the quest 'Paragons of Power: The Vindicator's Belt'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", zone = "Zul'Gurub" },
    [19824] = { ilvl = 61, k = "quest", name = "Zandalar Vindicator's Armguards", q = 4, quest = "Paragons of Power: The Vindicator's Armguards", req = 58, t = "Reward from the quest 'Paragons of Power: The Vindicator's Armguards'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", zone = "Zul'Gurub" },
    [19825] = { fac = "Alliance", ilvl = 65, k = "quest", name = "Zandalar Freethinker's Breastplate", q = 4, quest = "Paragons of Power: The Freethinker's Breastplate", req = 58, t = "Reward from the quest 'Paragons of Power: The Freethinker's Breastplate'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", zone = "Zul'Gurub" },
    [19826] = { fac = "Alliance", ilvl = 61, k = "quest", name = "Zandalar Freethinker's Belt", q = 4, quest = "Paragons of Power: The Freethinker's Belt", req = 58, t = "Reward from the quest 'Paragons of Power: The Freethinker's Belt'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", zone = "Zul'Gurub" },
    [19827] = { fac = "Alliance", ilvl = 61, k = "quest", name = "Zandalar Freethinker's Armguards", q = 4, quest = "Paragons of Power: The Freethinker's Armguards", req = 58, t = "Reward from the quest 'Paragons of Power: The Freethinker's Armguards'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", zone = "Zul'Gurub" },
