    [20640] = { fac = "Horde", ilvl = 45, k = "quest", name = "Southsea Head Bucket", q = 2, quest = "Southsea Shakedown", req = 40, t = "Reward from the quest 'Southsea Shakedown'. Pick it over the other reward choices. Starts with Security Chief Bilgewhizzle in Tanaris. Objective: Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.", zone = "Tanaris" },
