    [20642] = { fac = "Horde", ilvl = 47, k = "quest", name = "Antiquated Nobleman's Tunic", note = "beginning of the quest or chain", q = 2, quest = "Oran's Gratitude", req = 42, spots = "1458,73.4,32.4,H", t = "Reward from the quest 'Oran's Gratitude'. Pick it over the other reward choices. Starts with Oran Snakewrithe in Undercity. Objective: Now isn't this interesting? You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, &lt;class&gt;? Very interesting indeed. I thank you for your efforts in this matter. Our Dark Lady shall be very pleased with this discovery. Here, allow me to reward you proportionately.", zone = "The Hinterlands" },
