    [20723] = { fac = "Horde", ilvl = 62, k = "quest", name = "Brann's Trusty Pick", q = 2, quest = "Brann Bronzebeard's Lost Letter", req = 58, t = "Reward from the quest 'Brann Bronzebeard's Lost Letter'. Objective: Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.", zone = "Silithus" },
    [20724] = { ilvl = 62, k = "quest", name = "Corrupted Blackwood Staff", q = 2, quest = "Into The Maw of Madness", req = 58, t = "Reward from the quest 'Into The Maw of Madness'. Starts with Commander Mar'alith in Silithus. Objective: Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.And &lt;name&gt;, remember the Commander's words: \"Do what you must...\".", zone = "Silithus" },
