    [21178] = { ilvl = 62, k = "quest", name = "Gloves of Earthen Power", q = 3, quest = "Volunteer's Battlegear", req = 60, t = "Reward from the quest 'Volunteer's Battlegear'. Pick it over the other reward choices. Starts with Vargus in Silithus. Objective: Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest.", zone = "Silithus" },
    [21180] = { ilvl = 66, k = "quest", name = "Earthstrike", q = 4, quest = "Champion's Battlegear", req = 60, t = "Reward from the quest 'Champion's Battlegear'. Pick it over the other reward choices. Starts with Vargus in Silithus. Objective: Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus. You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest.", zone = "Silithus" },
    [21183] = { ilvl = 66, k = "quest", name = "Earthpower Vest", q = 3, quest = "Veteran's Battlegear", req = 60, t = "Reward from the quest 'Veteran's Battlegear'. Pick it over the other reward choices. Starts with Vargus in Silithus. Objective: Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Honored reputation with Cenarion Circle to be able to complete this quest.", zone = "Silithus" },
    [21184] = { ilvl = 62, k = "quest", name = "Deeprock Bracers", q = 4, quest = "Stalwart's Battlegear", req = 60, t = "Reward from the quest 'Stalwart's Battlegear'. Pick it over the other reward choices. Starts with Vargus in Silithus. Objective: Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus. You must also attain Revered reputation with Cenarion Circle to be able to complete this quest.", zone = "Silithus" },
