    [21200] = { fac = "Horde", ilvl = 80, k = "quest", name = "Signet Ring of the Bronze Dragonflight", q = 4, quest = "The Protector of Kalimdor", rep = "Brood of Nozdormu:Exalted", req = 60, t = "Reward from the quest 'The Protector of Kalimdor'. Starts with Anachronos in Tanaris. Objective: ProgressNever have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!Hand me your signet ring so that I may make the necessary adjustments.", zone = "Tanaris" },
    [21202] = { ilvl = 65, k = "quest", name = "Signet Ring of the Bronze Dragonflight", note = "beginning of the quest or chain", q = 4, quest = "The Path of the Conqueror", rep = "Brood of Nozdormu:Friendly", req = 60, spots = "1446,65.3,50,", t = "Reward from the quest 'The Path of the Conqueror'. Starts with Anachronos in Tanaris. Objective: ProgressYou honor my kind, &lt;name&gt;. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.You have earned another enhancement. Hand me your signet ring so that I may bolster its power.", zone = "Tanaris" },
