    [286978] = { ilvl = 23, k = "world", name = "Rotmender's Garb", note = "entrance to dungeon or raid", q = 3, req = 18, s = "world", spots = "1458,71.6,11.4,", t = "Drops in the Ruins of Lordaeron. Set piece of Rotmender's Raiment (Ruins of Lordaeron). (2) +5 Shadow Resistance. (3) +10 Intellect. (4) When mana falls below 15%, restore 200 mana over 10 sec, once every 5 min. Twice as much mana in Haunted and Wasteland. (5) Healing spells can heal for an additional 40 every 3 sec for 15 sec. Restoration: all five pieces are the hunt together at 19. On Horde the chest, sash, and gloves stay through 21. The treads stay in the top 3 through about 29.", zone = "Ruins of Lordaeron" },
    [286979] = { ilvl = 22, k = "world", name = "Rotmender's Gloves", note = "entrance to dungeon or raid", npc = "Stone Watcher", q = 3, req = 17, s = "world", spots = "1458,71.6,11.4,", t = "Drops from Stone Watcher in the Ruins of Lordaeron. Set piece of Rotmender's Raiment (Ruins of Lordaeron). (2) +5 Shadow Resistance. (3) +10 Intellect. (4) When mana falls below 15%, restore 200 mana over 10 sec, once every 5 min. Twice as much mana in Haunted and Wasteland. (5) Healing spells can heal for an additional 40 every 3 sec for 15 sec. Restoration: all five pieces are the hunt together at 19. On Horde the chest, sash, and gloves stay through 21. The treads stay in the top 3 through about 29.", zone = "Ruins of Lordaeron" },
    [286980] = { ilvl = 22, k = "world", name = "Rotmender's Sash", note = "entrance to dungeon or raid", npc = "Shrieking Banshee", q = 3, req = 17, s = "world", spots = "1458,71.6,11.4,", t = "Drops from Shrieking Banshee in the Ruins of Lordaeron. Set piece of Rotmender's Raiment (Ruins of Lordaeron). (2) +5 Shadow Resistance. (3) +10 Intellect. (4) When mana falls below 15%, restore 200 mana over 10 sec, once every 5 min. Twice as much mana in Haunted and Wasteland. (5) Healing spells can heal for an additional 40 every 3 sec for 15 sec. Restoration: all five pieces are the hunt together at 19. On Horde the chest, sash, and gloves stay through 21. The treads stay in the top 3 through about 29.", zone = "Ruins of Lordaeron" },
